struct Config { uint32_t x[2*MAX_DIM], y[2*MAX_DIM], mask[2*MASK_WORDS], mask_cols, mask_on, pad[2], center_on, center_x, center_y, center_size, direct_rgb; };
static uint8_t srcByte(uint32_t x,uint32_t y,uint32_t eye,uint32_t c){uint32_t v=c==0?(x*17+y*3+eye*53):c==1?(x*5+y*19+eye*97):(x*11+y*7+eye*31);return uint8_t(v&255u);}
static double toLinear(uint8_t b){double x=double(b)/255.0;return x<=0.04045?x/12.92:std::pow((x+0.055)/1.055,2.4);}
static double toSrgb(double x){return x<=0.0031308?12.92*x:1.055*std::pow(x,1.0/2.4)-0.055;}
